{"content": "def next_recovery(task):
    """
    Return 'wait', 'retry', or 'escalate' based on task state.
    """
    lease = task.get('lease', 'non-live')
    if lease == 'live':
        return 'wait'
    state = task.get('state', '')
    if state == 'queued':
        return 'retry'
    if state == 'failed':
        attempts = task.get('attempts', 0)
        max_attempts = task.get('max_attempts', 0)
        if attempts < max_attempts:
            return 'retry'
        else:
            return 'escalate'
    # Unknown state
    raise ValueError(f"Unknown state: {state}")
